import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        int n = sc.nextInt();

        int a = 0, b = 1;
        double target_ratio = x / y;
        double best_diff = 1e9;

        for (int i = 1; i <= n; i++) {
            int v1 = (int) Math.floor(target_ratio * i);
            int v2 = (int) Math.ceil(target_ratio * i);

            if (Math.abs(target_ratio - (double) v1 / i) + 1e-15 < best_diff) {
                a = v1;
                b = i;
                best_diff = Math.abs(target_ratio - (double) v1 / i);
            }
            if (Math.abs(target_ratio - (double) v2 / i) + 1e-15 < best_diff) {
                a = v2;
                b = i;
                best_diff = Math.abs(target_ratio - (double) v2 / i);
            }
        }

        int g = gcd(a, b);
        System.out.println((a / g) + "/" + (b / g));
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
